import type { Proc, Session, SessionGroup, Totals, Zombie, ZombieReason } from '../types'

export type PsRow = {
  pid: number
  ppid: number
  /** Process group: each Bash tool command's shell leads one, and its children stay in it. */
  pgid: number
  uid: number
  stat: string
  cpu: number
  rssKb: number
  /** lstart with its whitespace squashed; UTC when `ps` ran with TZ=UTC. */
  started: string
  command: string
}

/** A `~/.claude/sessions/<pid>.json` entry. The file can outlive a crashed session. */
export type HostEntry = {
  pid: number
  sessionId: string
  cwd: string
  name: string
  status: string
  procStart: string
}

/**
 * What a process inherited from the Claude Code session that spawned it: a Bash tool's
 * child gets the host's pid, an MCP server the session id alone.
 */
export type ProcEnv = { claudePid: number; sessionId: string | null } | { claudePid: null; sessionId: string }

export type Scan = {
  rows: PsRow[]
  entries: HostEntry[]
  env: Map<number, ProcEnv>
  cwd: Map<number, string>
  missingWorktrees: Set<string>
  missingSnapshots: Set<string>
  selfUid: number
  os: Os
}

export type Tally = { seen: Set<string>; tokensIn: number; tokensOut: number }

type Guard = { selfUid: number; protectedPids: ReadonlySet<number> }

type Host = { pid: number; cwd: string; session: Session }
type Item = { row: PsRow; depth: number }
type Claim =
  | { kind: 'live'; hostPid: number }
  | { kind: 'zombie'; reason: ZombieReason; sessionId: string | null; dir: string }

/** The systems the mod reads. Windows has no ps, process groups or /proc. */
export type Os = 'darwin' | 'linux'

/**
 * What differs between the systems: which binaries are the OS's or an app's
 * (never a session's child, never ours to signal), the toolchains among them
 * that sessions do run, whose environment the OS hides, and who adopts an orphan.
 */
type Rules = { system: RegExp; toolchain: RegExp; hiddenEnv: RegExp | null; isReaper: (row: PsRow) => boolean }
/** The user's systemd, wherever it is installed: NixOS keeps it in the store. */
const SYSTEMD_USER = /^\S*\/systemd --user\b/
const RULES: Record<Os, Rules> = {
  darwin: {
    system: /^\/(System|Applications|Library|usr\/libexec|usr\/sbin|sbin)\//,
    toolchain:
      /^\/(Library\/Java|Library\/Developer\/CommandLineTools|Library\/Frameworks\/Python\.framework|Applications\/Xcode[^/]*\.app\/Contents\/Developer)\//,
    // `ps eww` cannot read the environment of macOS's own binaries.
    hiddenEnv: /^\/(bin|usr\/bin)\//,
    // macOS has no subreapers: launchd adopts every orphan.
    isReaper: row => row.pid === 1,
  },
  linux: {
    system: /^\/(usr\/lib|usr\/libexec|usr\/share|usr\/sbin|sbin|lib|opt|snap)\//,
    toolchain: /^\/(usr\/lib\/jvm|usr\/lib\/dotnet|usr\/share\/dotnet)\//,
    // /proc/<pid>/environ is readable for every process of the same user.
    hiddenEnv: null,
    // An orphan goes to its nearest living subreaper, such as the user's systemd, or to init.
    isReaper: row => row.pid === 1 || SYSTEMD_USER.test(row.command),
  },
}

const PS_LINE =
  /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\S+)\s+([\d.]+)\s+(\d+)\s+(\w{3} \w{3}\s+\d+ [\d:]{8} \d{4})\s+(.*)$/
/** This mod's own probes, which run as children of the session hosting it. */
const PROBE =
  /^(ps -axww |ps axww |ps eww |lsof -b -w -a -d cwd |find \S+\/projects -maxdepth 2 -name |\/bin\/kill |\/bin\/sh -c echo |\/bin\/sh -c getconf |\/bin\/sh -c for p; do |tr \\0\\n |readlink \/proc\/\d+\/cwd$|id -u|uname -s|sysctl -n |\/bin\/sh -c \{ dd bs=1 skip=|dd bs=1 skip=\d+ count=0$|head -c 4194304$)/
const WORKTREE = /^(.*?\/\.claude\/worktrees\/[^/]+)(?:\/|$)/
/**
 * A Bash tool shell, or a subshell it forked (which keeps its command line), sourcing its
 * session's shell snapshot. Claude Code deletes the snapshot when the session exits.
 */
const SNAPSHOT =
  /^\/\S*\/(?:zsh|bash|sh) -c source (\/\S+\/shell-snapshots\/snapshot-(?:zsh|bash|sh)-\d+-[a-z0-9]+(?:-[\w-]+)?\.sh) /
const COMMAND_MAX = 400
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const squash = (text: string): string => text.trim().replace(/\s+/g, ' ')
const basename = (path: string): string => path.slice(path.lastIndexOf('/') + 1)
const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null
const textOf = (value: unknown): string => (typeof value === 'string' ? value : '')
const numberOf = (value: unknown): number => (typeof value === 'number' ? value : 0)
const sum = <T>(list: readonly T[], of: (item: T) => number): number =>
  list.reduce((total, item) => total + of(item), 0)
const isWithin = (path: string, dir: string): boolean => path === dir || path.startsWith(`${dir}/`)

/** A squashed lstart ("Tue Oct 6 14:13:53 2026") as milliseconds, to order two starts; NaN when it does not read. */
function timeOf(started: string): number {
  const [, month = '', day, clock = '', year] = started.split(' ')
  const [hours, minutes, seconds] = clock.split(':').map(Number)
  const index = MONTHS.indexOf(month)
  return index < 0 ? Number.NaN : Date.UTC(Number(year), index, Number(day), hours, minutes, seconds)
}

/** A Claude Code host: the desktop's bundled binary, a native `claude`, or the npm CLI. */
const isHostCommand = (command: string): boolean =>
  basename(squash(command.split(' -')[0] ?? '')) === 'claude' ||
  command.includes('@anthropic-ai/claude-code/cli')

const isCandidate = (row: PsRow, selfUid: number, rules: Rules): boolean =>
  row.pid > 1 &&
  row.uid === selfUid &&
  (!rules.system.test(row.command) || rules.toolchain.test(row.command)) &&
  !PROBE.test(row.command)

export function parsePs(stdout: string): PsRow[] {
  const rows: PsRow[] = []
  for (const line of stdout.split('\n')) {
    const match = PS_LINE.exec(line)
    if (match === null) continue
    const [, pid, ppid, pgid, uid, stat = '', cpu, rss, started = '', command = ''] = match
    rows.push({
      pid: Number(pid),
      ppid: Number(ppid),
      pgid: Number(pgid),
      uid: Number(uid),
      stat,
      cpu: Number(cpu),
      rssKb: Number(rss),
      started: squash(started),
      command,
    })
  }
  return rows
}

export function parseHost(json: string): HostEntry | null {
  let value: unknown
  try {
    value = JSON.parse(json)
  } catch {
    return null
  }
  if (!isRecord(value) || typeof value.pid !== 'number' || typeof value.sessionId !== 'string') {
    return null
  }
  return {
    pid: value.pid,
    sessionId: value.sessionId,
    cwd: textOf(value.cwd),
    name: textOf(value.name),
    status: textOf(value.status),
    procStart: squash(textOf(value.procStart)),
  }
}

/**
 * Each line is the pid, the command on macOS (`ps eww`), then the environment the process
 * started with. The command `commands` knows is cut off first, so an argument reading
 * `CLAUDE_PID=…` never passes for the environment.
 */
export function parseEnv(stdout: string, commands: ReadonlyMap<number, string>): Map<number, ProcEnv> {
  const found = new Map<number, ProcEnv>()
  for (const line of stdout.split('\n')) {
    const head = /^\s*(\d+)\s/.exec(line)
    if (head === null) continue
    const pid = Number(head[1])
    const rest = line.slice(head[0].length)
    const command = commands.get(pid)
    const env = ` ${command !== undefined && rest.startsWith(command) ? rest.slice(command.length) : rest}`
    const claudePid = /\sCLAUDE_PID=(\d+)(?:\s|$)/.exec(env)?.[1]
    const sessionId = /\sCLAUDE_CODE_SESSION_ID=([\w-]+)(?:\s|$)/.exec(env)?.[1]
    if (claudePid !== undefined) found.set(pid, { claudePid: Number(claudePid), sessionId: sessionId ?? null })
    else if (sessionId !== undefined) found.set(pid, { claudePid: null, sessionId })
  }
  return found
}

/** `lsof -Fpn` output: a `p<pid>` line, then an `n<path>` line for its cwd. */
export function parseCwd(stdout: string): Map<number, string> {
  const found = new Map<number, string>()
  let pid = 0
  for (const line of stdout.split('\n')) {
    if (line.startsWith('p')) pid = Number(line.slice(1))
    else if (line.startsWith('n') && pid > 0) found.set(pid, line.slice(1))
  }
  return found
}

/**
 * Adds each API response's usage once. A transcript writes one line per
 * content block, and every line of a response repeats the same usage.
 */
export function tallyUsage(lines: string, tally: Tally): void {
  for (const line of lines.split('\n')) {
    if (!line.includes('"usage"')) continue
    let row: unknown
    try {
      row = JSON.parse(line)
    } catch {
      continue
    }
    if (!isRecord(row) || row.type !== 'assistant' || !isRecord(row.message)) continue
    const { id, usage } = row.message
    if (typeof id !== 'string' || !isRecord(usage) || tally.seen.has(id)) continue
    tally.seen.add(id)
    tally.tokensIn +=
      numberOf(usage.input_tokens) +
      numberOf(usage.cache_creation_input_tokens) +
      numberOf(usage.cache_read_input_tokens)
    tally.tokensOut += numberOf(usage.output_tokens)
  }
}

export const worktreeOf = (path: string): string | null => WORKTREE.exec(path)?.[1] ?? null

export const snapshotOf = (command: string): string | null => SNAPSHOT.exec(command)?.[1] ?? null

/** When Claude Code wrote a shell snapshot: the epoch milliseconds in its name. */
export const bornOf = (snapshot: string): number => Number(/\/snapshot-[a-z]+-(\d+)-/.exec(snapshot)?.[1] ?? 0)

function placeOf(path: string): string {
  const root = worktreeOf(path)
  if (root === null) return basename(path)
  const [repo = '', name = ''] = root.split('/.claude/worktrees/')
  return `${basename(repo)} › ${name}`
}

function labelOf(command: string): string {
  const label = command
    .split(' ')
    .filter(Boolean)
    .map(word => (word.includes('/') ? basename(word) || word : word))
    .join(' ')
  return label.length > 72 ? `${label.slice(0, 71)}…` : label
}

function toProc(row: PsRow, depth: number): Proc {
  return {
    pid: row.pid,
    ppid: row.ppid,
    pgid: row.pgid,
    started: row.started,
    command: row.command.slice(0, COMMAND_MAX),
    label: labelOf(row.command),
    cpu: row.cpu,
    rssKb: row.rssKb,
    isDefunct: row.stat.includes('Z'),
    depth,
  }
}

/**
 * The sessions running now. A registry entry vouches for its pid only while
 * the start time matches, so a reused pid never revives a dead session, and
 * wherever the binary was installed; a Claude Code process with no entry
 * still counts, so its children are never taken for orphans.
 */
function hostsOf(
  rows: readonly PsRow[],
  entries: readonly HostEntry[],
  selfUid: number,
  rules: Rules,
): Map<number, Host> {
  const hosts = new Map<number, Host>()
  for (const row of rows) {
    if (row.uid !== selfUid) continue
    const entry = entries.find(one => one.pid === row.pid && one.procStart === row.started)
    if (entry === undefined && (rules.system.test(row.command) || !isHostCommand(row.command))) continue
    hosts.set(row.pid, {
      pid: row.pid,
      cwd: entry?.cwd ?? '',
      session: {
        sessionId: entry?.sessionId ?? '',
        pid: row.pid,
        name: entry === undefined ? `claude ${row.pid}` : entry.name || `session ${entry.sessionId.slice(0, 8)}`,
        status: entry?.status || 'running',
        place: entry === undefined ? 'unregistered session' : placeOf(entry.cwd),
        tokensIn: 0,
        tokensOut: 0,
      },
    })
  }
  return hosts
}

function childrenOf(rows: readonly PsRow[]): Map<number, PsRow[]> {
  const kids = new Map<number, PsRow[]>()
  for (const row of rows) {
    if (row.pid === row.ppid || PROBE.test(row.command)) continue
    const list = kids.get(row.ppid)
    if (list === undefined) kids.set(row.ppid, [row])
    else list.push(row)
  }
  return kids
}

/** `pid`'s descendants depth-first, stopping at another session's host. */
function descend(pid: number, kids: Map<number, PsRow[]>, hosts: Map<number, Host>, depth: number): Item[] {
  return (kids.get(pid) ?? []).flatMap(row =>
    hosts.has(row.pid) ? [] : [{ row, depth }, ...descend(row.pid, kids, hosts, depth + 1)],
  )
}

function liveTrees(rows: readonly PsRow[], entries: readonly HostEntry[], selfUid: number, rules: Rules) {
  const hosts = hostsOf(rows, entries, selfUid, rules)
  const kids = childrenOf(rows)
  const owner = new Map<number, number>()
  const order = new Map<number, Item[]>()
  for (const host of hosts.values()) {
    const items = descend(host.pid, kids, hosts, 0)
    for (const item of items) owner.set(item.row.pid, host.pid)
    order.set(host.pid, items)
  }
  // What a live session runs inside (a terminal, tmux, an editor) is in use, however it started:
  // it is never a zombie, nor in one's tree.
  const byPid = new Map(rows.map(row => [row.pid, row]))
  for (const host of hosts.values()) {
    let up = byPid.get(byPid.get(host.pid)?.ppid ?? 0)
    for (let hop = 0; up !== undefined && up.pid > 1 && !rules.isReaper(up) && hop < 64; hop += 1) {
      if (!hosts.has(up.pid) && !owner.has(up.pid)) owner.set(up.pid, host.pid)
      up = byPid.get(up.ppid)
    }
  }
  return { hosts, kids, owner, order, byPid }
}

/** Processes outside every live session's tree: the ones whose env and cwd are worth reading. */
export function candidatesOf(
  rows: readonly PsRow[],
  entries: readonly HostEntry[],
  selfUid: number,
  os: Os,
): number[] {
  const rules = RULES[os]
  const { hosts, owner } = liveTrees(rows, entries, selfUid, rules)
  return rows
    .filter(row => !owner.has(row.pid) && !hosts.has(row.pid) && isCandidate(row, selfUid, rules))
    .map(row => row.pid)
}

/**
 * Sorts every process into a live session or a zombie. Ancestry decides
 * first, then what a process carries (the session it inherited, a shell
 * snapshot its session deleted), and the worktree a process sits in last,
 * only where nothing in its tree or Bash command carries any of that, since
 * a session often works outside its own folder. A process with none of these
 * follows its group.
 */
export function classify(scan: Scan): { groups: SessionGroup[]; zombies: Zombie[] } {
  const { rows, env, cwd } = scan
  const rules = RULES[scan.os]
  const { hosts, kids, owner, order, byPid } = liveTrees(rows, scan.entries, scan.selfUid, rules)
  // Who adopts an orphan: launchd on macOS; init or the nearest subreaper on Linux.
  const reapers = new Set([1, ...rows.filter(row => rules.isReaper(row)).map(row => row.pid)])
  // A session works in its own folder, and one in a repository's main checkout in its worktrees
  // too, while they exist.
  const hostIn = (root: string) => {
    const repo = root.slice(0, root.indexOf('/.claude/worktrees/'))
    const isGone = scan.missingWorktrees.has(root)
    return [...hosts.values()].find(
      host =>
        isWithin(host.cwd, root) || (!isGone && isWithin(host.cwd, repo) && worktreeOf(host.cwd) === null),
    )
  }

  // What a process carries: the session it inherited, or a shell snapshot its session deleted.
  const evidenceOf = (row: PsRow): Claim | null => {
    const dir = cwd.get(row.pid) ?? ''
    const inherited = env.get(row.pid)
    if (inherited !== undefined) {
      // Its host is the one it names if that was already running when this process started: a
      // process that reused the pid since started later. The session id names a Bash tool child's
      // host no better, since /clear gives a running host a new one; an MCP server has no other.
      const host =
        inherited.claudePid === null
          ? [...hosts.values()].find(one => one.session.sessionId === inherited.sessionId)
          : hosts.get(inherited.claudePid)
      const isItsHost = host !== undefined && !(timeOf(byPid.get(host.pid)?.started ?? '') > timeOf(row.started))
      return isItsHost
        ? { kind: 'live', hostPid: host.pid }
        : { kind: 'zombie', reason: 'session-ended', sessionId: inherited.sessionId, dir }
    }
    const snapshot = snapshotOf(row.command)
    if (snapshot !== null && scan.missingSnapshots.has(snapshot)) {
      return { kind: 'zombie', reason: 'session-ended', sessionId: null, dir }
    }
    return null
  }
  // Where it sits. Without the env, only an orphan may be judged by its folder: a person's own
  // shell in a worktree always has a live parent (a terminal, login, tmux, an editor).
  const folderClaimOf = (row: PsRow): Claim | null => {
    const root = reapers.has(row.ppid) ? worktreeOf(cwd.get(row.pid) ?? '') : null
    if (root === null) return null
    const host = hostIn(root)
    if (host !== undefined) return { kind: 'live', hostPid: host.pid }
    const reason = scan.missingWorktrees.has(root) ? 'worktree-deleted' : 'no-live-session'
    return { kind: 'zombie', reason, sessionId: null, dir: root }
  }

  // A process group is one Bash tool command, and POSIX keeps a group's id from reuse while any
  // member lives.
  const jobs = new Map<number, PsRow[]>()
  for (const row of rows) {
    const job = jobs.get(row.pgid)
    if (job === undefined) jobs.set(row.pgid, [row])
    else job.push(row)
  }

  const undead = new Map<number, Extract<Claim, { kind: 'zombie' }>>()
  const settle = (row: PsRow, claim: Claim) => {
    if (claim.kind === 'zombie') {
      undead.set(row.pid, claim)
      return
    }
    // Detached from its session's tree (adopted by a reaper), but the session still runs.
    const items = [{ row, depth: 0 }, ...descend(row.pid, kids, hosts, 1)].filter(
      item => !owner.has(item.row.pid),
    )
    for (const item of items) owner.set(item.row.pid, claim.hostPid)
    order.get(claim.hostPid)?.push(...items)
  }
  const isOpen = (row: PsRow) => !owner.has(row.pid) && !hosts.has(row.pid) && isCandidate(row, scan.selfUid, rules)
  for (const row of rows) {
    const claim = isOpen(row) ? evidenceOf(row) : null
    if (claim !== null) settle(row, claim)
  }
  // The folder decides last, and only for a process whose tree and Bash command carry no evidence:
  // a session in the repository's main checkout must not adopt what a dead session's processes
  // prove dead.
  const isSettled = (pid: number) => owner.has(pid) || undead.has(pid)
  for (const row of rows) {
    if (!isOpen(row) || undead.has(row.pid)) continue
    const near = [...descend(row.pid, kids, hosts, 1).map(item => item.row), ...(jobs.get(row.pgid) ?? [])]
    if (near.some(one => one.pid !== row.pid && isSettled(one.pid))) continue
    const claim = folderClaimOf(row)
    if (claim !== null) settle(row, claim)
  }

  // A member of a group with no evidence of its own (macOS hides the env of its own binaries)
  // goes with a dead sibling, unless something in the group is still owned or not ours.
  for (const job of jobs.values()) {
    const claim = job.map(row => undead.get(row.pid)).find(found => found !== undefined)
    const isLeftover = job.every(
      row => !owner.has(row.pid) && !hosts.has(row.pid) && isCandidate(row, scan.selfUid, rules),
    )
    if (claim === undefined || !isLeftover) continue
    for (const row of job) if (!undead.has(row.pid)) undead.set(row.pid, claim)
  }

  // A shell from /bin whose env macOS keeps from us: a `zsh -c` a dead session left running.
  const isBareShell = (row: PsRow) =>
    row.uid === scan.selfUid &&
    rules.hiddenEnv !== null &&
    rules.hiddenEnv.test(row.command) &&
    !env.has(row.pid) &&
    !owner.has(row.pid)
  /** The orphan atop `row`, when every process between them is the same leftover; null otherwise. */
  const orphanOf = (row: PsRow): PsRow | null => {
    let current = row
    for (let hop = 0; hop < 64; hop += 1) {
      if (reapers.has(current.ppid)) return current
      const parent = byPid.get(current.ppid)
      if (parent === undefined || !(undead.has(parent.pid) || isBareShell(parent))) return null
      current = parent
    }
    return null
  }
  const tops = new Map<number, Extract<Claim, { kind: 'zombie' }>>()
  for (const row of rows) {
    const claim = undead.get(row.pid)
    if (claim === undefined || owner.has(row.pid)) continue
    const top = orphanOf(row)
    if (top !== null && !tops.has(top.pid)) tops.set(top.pid, undead.get(top.pid) ?? claim)
  }

  const zombies: Zombie[] = []
  const inTree = new Set<number>()
  for (const row of rows) {
    const claim = tops.get(row.pid)
    if (claim === undefined || inTree.has(row.pid)) continue
    const items = [{ row, depth: 0 }, ...descend(row.pid, kids, hosts, 1)].filter(
      item => !owner.has(item.row.pid) && !inTree.has(item.row.pid),
    )
    for (const item of items) inTree.add(item.row.pid)
    const entry =
      claim.sessionId === null ? undefined : scan.entries.find(one => one.sessionId === claim.sessionId)
    const place = entry !== undefined ? placeOf(entry.cwd) : placeOf(claim.dir) || 'an unknown folder'
    zombies.push({
      root: toProc(row, 0),
      children: items.slice(1).map(item => toProc(item.row, item.depth)),
      reason: claim.reason,
      place,
      session:
        claim.sessionId === null
          ? null
          : {
              sessionId: claim.sessionId,
              pid: null,
              name: entry?.name || `session ${claim.sessionId.slice(0, 8)}`,
              status: 'ended',
              place,
              tokensIn: 0,
              tokensOut: 0,
            },
    })
  }

  const groups = [...hosts.values()].map(host => ({
    session: host.session,
    procs: (order.get(host.pid) ?? []).map(item => toProc(item.row, item.depth)),
  }))
  groups.sort(
    (a, b) =>
      Number(b.session.status === 'busy') - Number(a.session.status === 'busy') ||
      a.session.name.localeCompare(b.session.name),
  )
  zombies.sort((a, b) => a.place.localeCompare(b.place) || a.root.pid - b.root.pid)
  return { groups, zombies }
}

export function totalsOf(groups: readonly SessionGroup[], zombies: readonly Zombie[]): Totals {
  const procs = [
    ...groups.flatMap(group => group.procs),
    ...zombies.flatMap(zombie => [zombie.root, ...zombie.children]),
  ]
  const sessions = new Map<string, Session>()
  for (const session of [
    ...groups.map(group => group.session),
    ...zombies.flatMap(zombie => (zombie.session === null ? [] : [zombie.session])),
  ]) {
    sessions.set(session.sessionId || `pid:${session.pid}`, session)
  }
  return {
    procs: procs.length,
    cpu: sum(procs, proc => proc.cpu),
    rssKb: sum(procs, proc => proc.rssKb),
    tokensIn: sum([...sessions.values()], session => session.tokensIn),
    tokensOut: sum([...sessions.values()], session => session.tokensOut),
  }
}

/**
 * How many zombies the board counts: every process in the zombie trees, a
 * zombie's children included, so the number matches the rows. A defunct one
 * counts too: it is never signalled, but it goes once its parent does.
 */
export const zombieTotal = (zombies: readonly Zombie[]): number =>
  zombies.reduce((total, zombie) => total + 1 + zombie.children.length, 0)

/** How many rows a kill cleared: the signalled pids, and the defunct children they left to a reaper. */
export function laidToRest(zombies: readonly Zombie[], signalled: ReadonlySet<number>): number {
  const cleared = zombies
    .flatMap(zombie => [zombie.root, ...zombie.children])
    .filter(proc => signalled.has(proc.pid) || (proc.isDefunct && signalled.has(proc.ppid)))
  return new Set(cleared.map(proc => proc.pid)).size
}

/**
 * The living members of these zombies' trees, deepest first, so no
 * parent dies before its children and hands them to a reaper mid-kill.
 * A defunct process is already dead: it goes once its parent does.
 */
export function killOrder(zombies: readonly Zombie[]): Proc[] {
  return zombies
    .flatMap(zombie => [zombie.root, ...zombie.children])
    .filter(proc => !proc.isDefunct)
    .sort((a, b) => b.depth - a.depth)
}

/** The planned pids that still name the very process the board showed, and that are ours to signal. */
export function stillSame(planned: readonly Proc[], rows: readonly PsRow[], guard: Guard): number[] {
  const now = new Map(rows.map(row => [row.pid, row]))
  return planned
    .filter(proc => {
      const row = now.get(proc.pid)
      return (
        row !== undefined &&
        row.pid > 1 &&
        row.uid === guard.selfUid &&
        !guard.protectedPids.has(row.pid) &&
        !isHostCommand(row.command) &&
        !row.stat.includes('Z') &&
        row.started === proc.started &&
        row.command.slice(0, COMMAND_MAX) === proc.command
      )
    })
    .map(proc => proc.pid)
}

export function bytes(count: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let value = count
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit += 1
  }
  return `${unit === 0 || value >= 10 ? Math.round(value) : value.toFixed(1)} ${units[unit]}`
}

export const memory = (kb: number): string => bytes(kb * 1024)

export function count(value: number): string {
  if (value >= 1e9) return `${(value / 1e9).toFixed(1)}B`
  if (value >= 1e6) return `${(value / 1e6).toFixed(1)}M`
  if (value >= 1e3) return `${(value / 1e3).toFixed(1)}k`
  return String(value)
}

files.hooks/panels.ts:
import type { Snapshot } from '../types'
import { count, memory, zombieTotal } from './model'
import { ACTORS, ICON_COIN, ICON_GEAR, ICON_TERMINAL, ICON_ZOMBIE, meter, pixels, scene } from './sprites'
import type { Sprite } from './sprites'

/**
 * Everything the board shows, bar its buttons, is drawn here as SVG in one
 * monospace face: the surfaces draw Text in their own proportional font, and
 * no prop changes it.
 */

/** A drawing and the size it is meant to be shown at, in CSS pixels. */
export type Drawing = { source: string; width: number; height: number; alt: string }

/** One process row of a card's table. */
export type Line = { pid: number; cpu: string; mem: string; command: string; isFaint: boolean }

/** The night palette of the screen at the top. */
export const NIGHT = {
  ground: '#1d1934',
  slot: '#2a2448',
  slotFrame: '#3d3570',
  frame: '#4c4480',
  label: '#a99fd0',
  value: '#f3e6c4',
  alarm: '#ff8a7a',
  calm: '#93cf87',
}

/**
 * The pastel palette of the cards and headings. They keep their own colours
 * on either theme, so their ink is their own too.
 */
const DAY = {
  ink: '#3d2f4a',
  soft: '#7d6f8c',
  faint: '#a094b4',
  rule: '#e3dcf2',
  alarm: '#c2413a',
}

/** Badge looks: a session's state, and a zombie being killed. */
const BADGES: Readonly<Record<string, { ink: string; ground: string; mark: string }>> = {
  busy: { ink: '#2c7a4b', ground: '#d4f2dd', mark: '●' },
  running: { ink: '#2c7a4b', ground: '#d4f2dd', mark: '●' },
  waiting: { ink: '#8a5d00', ground: '#ffefc4', mark: '◐' },
  idle: { ink: '#6f6385', ground: '#ebe6f6', mark: '○' },
  killing: { ink: '#8a3a4e', ground: '#ffe0e8', mark: '◌' },
}

/** Section strips: the icon, the tint, and the ink of each. */
type Strip = 'zombies' | 'sessions' | 'quiet'
const STRIPS: Readonly<Record<Strip, { icon: Sprite; ground: string; ink: string }>> = {
  zombies: { icon: ICON_ZOMBIE, ground: '#ffe3ea', ink: '#7a2f45' },
  sessions: { icon: ICON_TERMINAL, ground: '#ebe5ff', ink: '#4a3d7a' },
  quiet: { icon: ICON_ZOMBIE, ground: '#dcf2e3', ink: '#2c6b45' },
}

const MONO = "ui-monospace, 'SF Mono', SFMono-Regular, Menlo, Monaco, Consolas, monospace"
/** One monospace column is about 0.6em wide; CJK and emoji take two. */
const ADVANCE = 0.6
const WIDE = /[ᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦]|\p{Extended_Pictographic}/u

/** The screen: the graveyard scene is 128 pixels drawn three times over. */
const SCALE = 3
const SCREEN_W = 384
const BANNER_H = 132
const PAD = 10
const GAP = 8
const SLOT_H = 68
const METER_SEGMENTS = 24
const GAUGE_H = 22
/** A gauge's reading in three fixed stops, so both rows line up at value, slash and total. */
const VALUE_END = 298
const SLASH_AT = 307
const TOTAL_START = 316
const ICON_BOX = 24
const TITLE_SIZE = 13
const SUBTITLE_SIZE = 11
const BODY_SIZE = 12

/**
 * Ambient motion, all of it in CSS inside the drawing: it runs without the mod
 * drawing anything again, and stops for anyone who asked for less motion.
 */
const MOTION =
  '<style>' +
  '.twinkle{animation:twinkle 2.4s steps(1,end) infinite}' +
  '@keyframes twinkle{0%,100%{opacity:1}50%{opacity:.3}}' +
  '.glow{animation:glow 3.2s ease-in-out infinite}' +
  '@keyframes glow{0%,100%{opacity:.2}50%{opacity:1}}' +
  '@media (prefers-reduced-motion:reduce){.twinkle,.glow{animation:none}}' +
  '</style>'

/** The still scene never changes, so it is drawn once. */
const SCENE = pixels(scene(), 0, 0, SCALE)
const fragments = new Map<Sprite, string>()
/** A 12-pixel icon at twice its size, drawn once and placed by translation after that. */
const icon = (sprite: Sprite, x: number, y: number): string => {
  let fragment = fragments.get(sprite)
  if (fragment === undefined) {
    fragment = pixels(sprite, 0, 0, 2)
    fragments.set(sprite, fragment)
  }
  return `<g transform="translate(${x} ${y})">${fragment}</g>`
}

const columnsOf = (text: string): number =>
  [...text].reduce((total, char) => total + (WIDE.test(char) ? 2 : 1), 0)

/** `text` cut to `columns`, an ellipsis standing for the rest. */
export function clip(text: string, columns: number): string {
  if (columnsOf(text) <= columns) return text
  let kept = ''
  let used = 0
  for (const char of text) {
    const width = WIDE.test(char) ? 2 : 1
    if (used + width > columns - 1) break
    kept += char
    used += width
  }
  return `${kept}…`
}

const escape = (text: string): string =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

type Style = { size: number; fill: string; isBold?: boolean; anchor?: 'start' | 'middle' | 'end'; spacing?: number }

function text(x: number, y: number, content: string, style: Style): string {
  const bold = style.isBold === true ? ' font-weight="bold"' : ''
  const anchor = style.anchor !== undefined && style.anchor !== 'start' ? ` text-anchor="${style.anchor}"` : ''
  const spacing = style.spacing !== undefined ? ` letter-spacing="${style.spacing}"` : ''
  return (
    `<text x="${x}" y="${y}" font-family="${MONO}" font-size="${style.size}" fill="${style.fill}"${bold}${anchor}${spacing}>` +
    `${escape(content)}</text>`
  )
}

const drawing = (width: number, height: number, body: string, alt: string): Drawing => ({
  source: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">${body}</svg>`,
  width,
  height,
  alt,
})

const share = (part: number, whole: number): number => (whole > 0 ? part / whole : 0)

type Counter = { icon: Sprite; value: string; label: string; tone: string }

/** A slot of the status window: icon over value over label, all on one centre line. */
function slot(x: number, y: number, width: number, counter: Counter): string {
  const centre = x + width / 2
  return (
    `<rect x="${x}" y="${y}" width="${width}" height="${SLOT_H}" rx="8" fill="${NIGHT.slot}" stroke="${NIGHT.slotFrame}"/>` +
    icon(counter.icon, centre - ICON_BOX / 2, y + 9) +
    text(centre, y + 50, counter.value, { size: 17, fill: counter.tone, isBold: true, anchor: 'middle' }) +
    text(centre, y + 62, counter.label, { size: 9, fill: NIGHT.label, anchor: 'middle', spacing: 1 })
  )
}

/** The tokens slot: the coin on the centre line, each figure over its own label, a rule between them. */
function tokens(x: number, y: number, width: number, spentIn: string, spentOut: string): string {
  const centre = x + width / 2
  const halves: Array<[number, string, string]> = [
    [x + width / 4, spentIn, 'TOKENS IN'],
    [x + (width * 3) / 4, spentOut, 'TOKENS OUT'],
  ]
  return (
    `<rect x="${x}" y="${y}" width="${width}" height="${SLOT_H}" rx="8" fill="${NIGHT.slot}" stroke="${NIGHT.slotFrame}"/>` +
    icon(ICON_COIN, centre - ICON_BOX / 2, y + 9) +
    `<rect x="${centre - 0.5}" y="${y + 38}" width="1" height="${SLOT_H - 46}" fill="${NIGHT.slotFrame}"/>` +
    halves
      .map(
        ([middle, value, label]) =>
          text(middle, y + 50, value, { size: 17, fill: NIGHT.value, isBold: true, anchor: 'middle' }) +
          text(middle, y + 62, label, { size: 9, fill: NIGHT.label, anchor: 'middle', spacing: 1 }),
      )
      .join('')
  )
}

/** A meter row: label, segments, then value / total, each on its own stop. */
function gauge(y: number, label: string, fraction: number, value: string, total: string): string {
  const baseline = y + 13
  return (
    text(PAD + 2, baseline, label, { size: 11, fill: NIGHT.label, isBold: true }) +
    pixels(meter(fraction, METER_SEGMENTS), PAD + 36, y + 3, 2) +
    text(VALUE_END, baseline, value, { size: BODY_SIZE, fill: NIGHT.value, isBold: true, anchor: 'end' }) +
    (total === ''
      ? ''
      : text(SLASH_AT, baseline, '/', { size: BODY_SIZE, fill: NIGHT.label, anchor: 'middle' }) +
        text(TOTAL_START, baseline, total, { size: BODY_SIZE, fill: NIGHT.label }))
  )
}

/** What moves over the scene: stars and fireflies, each out of step with the next. */
function actors(): string {
  const offset = (index: number, period: number) => `animation-delay:-${((index * 0.37) % 1) * period}s`
  const stars = ACTORS.stars.map(
    (star, index) =>
      `<g class="twinkle" style="${offset(index, 2.4)}">${pixels(star.sprite, star.x * SCALE, star.y * SCALE, SCALE)}</g>`,
  )
  const flies = ACTORS.fireflies.map(
    (fly, index) =>
      `<g class="glow" style="${offset(index, 3.2)}">${pixels(fly.sprite, fly.x * SCALE, fly.y * SCALE, SCALE)}</g>`,
  )
  return [...stars, ...flies].join('')
}

/** The scene and what moves over it never change, so they are drawn once. */
const BACKDROP = SCENE + actors()

let lastScreen: { key: string; drawing: Drawing } | undefined

/**
 * The graveyard and its status window as one picture, so nothing in it can
 * drift out of line. Built again only when what it shows has changed.
 */
export function screen(snap: Snapshot): Drawing {
  const { totals, machine } = snap
  const zombies = zombieTotal(snap.zombies)
  const key = JSON.stringify([snap.groups.length, zombies, totals, machine])
  if (lastScreen?.key === key) return lastScreen.drawing
  const third = (SCREEN_W - PAD * 2 - GAP * 2) / 3
  const full = SCREEN_W - PAD * 2
  const parts = [BACKDROP]
  let y = BANNER_H + PAD
  const counters: Counter[] = [
    { icon: ICON_TERMINAL, value: String(snap.groups.length), label: 'SESSIONS', tone: NIGHT.value },
    { icon: ICON_GEAR, value: String(totals.procs), label: 'PROCESSES', tone: NIGHT.value },
    { icon: ICON_ZOMBIE, value: String(zombies), label: 'ZOMBIES', tone: zombies > 0 ? NIGHT.alarm : NIGHT.calm },
  ]
  counters.forEach((counter, index) => parts.push(slot(PAD + index * (third + GAP), y, third, counter)))
  y += SLOT_H + GAP + 2
  const cores = machine.cores > 0 ? `${machine.cores} cores` : ''
  const ram = machine.memoryKb > 0 ? memory(machine.memoryKb) : ''
  parts.push(gauge(y, 'CPU', share(totals.cpu, machine.cores * 100), `${totals.cpu.toFixed(1)}%`, cores))
  y += GAUGE_H
  parts.push(gauge(y, 'MEM', share(totals.rssKb, machine.memoryKb), memory(totals.rssKb), ram))
  y += GAUGE_H + GAP
  parts.push(tokens(PAD, y, full, count(totals.tokensIn), count(totals.tokensOut)))
  const height = y + SLOT_H + PAD
  const body =
    MOTION +
    `<defs><clipPath id="screen"><rect width="${SCREEN_W}" height="${height}" rx="12"/></clipPath></defs>` +
    `<g clip-path="url(#screen)"><rect width="${SCREEN_W}" height="${height}" fill="${NIGHT.ground}"/>${parts.join('')}</g>` +
    `<rect x="0.75" y="0.75" width="${SCREEN_W - 1.5}" height="${height - 1.5}" rx="11.5" fill="none" stroke="${NIGHT.frame}" stroke-width="1.5"/>`
  const alt =
    `${snap.groups.length} sessions, ${totals.procs} processes, ${zombies} zombies; ` +
    `CPU ${totals.cpu.toFixed(1)}%, memory ${memory(totals.rssKb)}; ` +
    `tokens ${count(totals.tokensIn)} in, ${count(totals.tokensOut)} out`
  lastScreen = { key, drawing: drawing(SCREEN_W, height, body, alt) }
  return lastScreen.drawing
}

const STRIP_H = 30
const STRIP_PAD = 8
const LABEL_SPACING = 0.5
const CHEVRON_W = 10

/**
 * A section's heading: a tinted strip with its icon and label, and, when the
 * section folds, a chevron at its right end (down while closed, up when open).
 * It reads the same on a light or a dark page.
 */
export function strip(kind: Strip, label: string, fold: 'open' | 'closed' | null): Drawing {
  const look = STRIPS[kind]
  const labelX = STRIP_PAD + ICON_BOX + 10
  // Letter spacing widens every column, so it counts toward the width too.
  const labelW = columnsOf(label) * (TITLE_SIZE * ADVANCE + LABEL_SPACING) - LABEL_SPACING
  const chevronX = labelX + labelW + 14
  const width = Math.ceil((fold === null ? labelX + labelW : chevronX + CHEVRON_W) + STRIP_PAD + 2)
  const middle = STRIP_H / 2
  const chevron =
    fold === null
      ? ''
      : `<path d="M${chevronX} ${fold === 'closed' ? middle - 2 : middle + 2}l${CHEVRON_W / 2} ${fold === 'closed' ? 4 : -4}l${CHEVRON_W / 2} ${fold === 'closed' ? -4 : 4}" ` +
        `fill="none" stroke="${look.ink}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`
  const body =
    `<rect width="${width}" height="${STRIP_H}" rx="8" fill="${look.ground}"/>` +
    icon(look.icon, STRIP_PAD, (STRIP_H - ICON_BOX) / 2) +
    text(labelX, 20, label, { size: TITLE_SIZE, fill: look.ink, isBold: true, spacing: LABEL_SPACING }) +
    chevron
  const state = fold === null ? '' : fold === 'open' ? ', open' : ', closed'
  return drawing(width, STRIP_H, body, `${label}${state}`)
}

/** A line of text on the page: an empty state, an error, a wait. */
export function note(message: string, tone: 'soft' | 'alarm'): Drawing {
  const width = Math.ceil(columnsOf(message) * BODY_SIZE * ADVANCE + 4)
  const fill = tone === 'alarm' ? DAY.alarm : DAY.soft
  return drawing(width, 18, text(0, 13, message, { size: BODY_SIZE, fill }), message)
}

/** A card's head: its icon in a fixed box, so every title starts on the same line, then title over subtitle. */
export function header(sprite: Sprite, title: string, subtitle: string, widthPx: number): Drawing {
  const textX = ICON_BOX + 10
  const room = Math.max(40, widthPx - textX)
  const titleText = clip(title, Math.floor(room / (TITLE_SIZE * ADVANCE)))
  const subtitleText = clip(subtitle, Math.floor(room / (SUBTITLE_SIZE * ADVANCE)))
  const used = Math.max(
    columnsOf(titleText) * TITLE_SIZE * ADVANCE,
    columnsOf(subtitleText) * SUBTITLE_SIZE * ADVANCE,
  )
  const width = Math.ceil(textX + used + 2)
  const body =
    icon(sprite, 0, 6) +
    text(textX, 16, titleText, { size: TITLE_SIZE, fill: DAY.ink, isBold: true }) +
    text(textX, 31, subtitleText, { size: SUBTITLE_SIZE, fill: DAY.soft })
  return drawing(width, 36, body, `${title}. ${subtitle}`)
}

const TABLE_SIZE = 11
const ROW_H = 17
const COLUMNS = [
  { title: 'PID', width: 6 },
  { title: 'CPU', width: 6 },
  { title: 'MEM', width: 8 },
] as const

/** A card's processes: numbers flush right in fixed columns, the command after them, then how many more. */
export function table(lines: readonly Line[], more: number, widthPx: number): Drawing {
  const advance = TABLE_SIZE * ADVANCE
  const gap = 2 * advance
  const edges: number[] = []
  let x = 0
  for (const column of COLUMNS) {
    x += column.width * advance
    edges.push(x)
    x += gap
  }
  const commandX = x
  const commandColumns = Math.max(12, Math.floor((widthPx - commandX) / advance))
  const width = Math.ceil(commandX + commandColumns * advance)
  const head =
    COLUMNS.map((column, index) =>
      text(edges[index] ?? 0, 11, column.title, { size: 9, fill: DAY.faint, anchor: 'end', spacing: 0.5 }),
    ).join('') +
    text(commandX, 11, 'COMMAND', { size: 9, fill: DAY.faint, spacing: 0.5 }) +
    `<rect x="0" y="16" width="${width}" height="1" fill="${DAY.rule}"/>`
  const rows = lines.map((line, index) => {
    const y = 31 + index * ROW_H
    const ink = line.isFaint ? DAY.faint : DAY.ink
    const cells = [String(line.pid), line.cpu, line.mem]
    return (
      cells
        .map((cell, column) => text(edges[column] ?? 0, y, cell, { size: TABLE_SIZE, fill: ink, anchor: 'end' }))
        .join('') + text(commandX, y, clip(line.command, commandColumns), { size: TABLE_SIZE, fill: ink })
    )
  })
  if (more > 0) {
    rows.push(text(commandX, 31 + lines.length * ROW_H, `+ ${more} more`, { size: TABLE_SIZE, fill: DAY.faint }))
  }
  const height = 20 + rows.length * ROW_H
  return drawing(width, height, head + rows.join(''), `${lines.length + more} processes`)
}

/** A badge in a card's right-hand column, every badge as wide as the longest so they line up. */
export function pill(status: string): Drawing {
  const look = BADGES[status] ?? BADGES.idle ?? { ink: DAY.soft, ground: DAY.rule, mark: '○' }
  const label = `${look.mark} ${status}`
  const width = Math.ceil(columnsOf('◐ waiting') * 11 * ADVANCE + 16)
  const body =
    `<rect width="${width}" height="20" rx="10" fill="${look.ground}"/>` +
    text(width / 2, 14, label, { size: 11, fill: look.ink, isBold: true, anchor: 'middle' })
  return drawing(width, 20, body, status)
}

const NOTICE_SIZE = 13
/** Zombie red that reads on a light or a dark prompt band. */
const NOTICE_INK = '#d0584f'

/**
 * The zombie's face and a line of text as one drawing, so the two share a
 * centre line; a Text beside an Svg sits on its own baseline instead.
 */
export function notice(message: string): Drawing {
  const textX = ICON_BOX + 8
  const width = Math.ceil(textX + columnsOf(message) * NOTICE_SIZE * ADVANCE + 2)
  const body = icon(ICON_ZOMBIE, 0, 0) + text(textX, 17, message, { size: NOTICE_SIZE, fill: NOTICE_INK, isBold: true })
  return drawing(width, ICON_BOX, body, message)
}

export const icons = { zombie: ICON_ZOMBIE, terminal: ICON_TERMINAL } as const

files.hooks/scan.ts:
import type { FsEntry, FsStat, ProcessRunInit, ProcessRunResult } from 'claude-code'

import type { Machine, Snapshot } from '../types'
import {
  bornOf,
  candidatesOf,
  classify,
  parseCwd,
  parseEnv,
  parseHost,
  parsePs,
  snapshotOf,
  tallyUsage,
  totalsOf,
  worktreeOf,
} from './model'
import type { HostEntry, Os, ProcEnv, PsRow, Tally } from './model'

/**
 * The session host this mod runs in, the user it runs as, the folder Claude Code keeps its
 * sessions and transcripts in, their system, and the machine.
 */
export type Context = { configDir: string; os: Os; selfUid: number; selfHostPid: number; machine: Machine }

/**
 * The host calls a scan makes. The engine only takes `$` spelled out at each
 * call site, so the hook that owns `$` hands these over as closures.
 */
export type Io = {
  run: (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult>
  exists: (path: string) => Promise<boolean>
  list: (path: string) => Promise<FsEntry[]>
  read: (path: string) => Promise<string>
  stat: (path: string) => Promise<FsStat>
  home: () => Promise<string | undefined>
  /** CLAUDE_CONFIG_DIR, which Claude Code uses in place of ~/.claude when it is set. */
  configDir: () => Promise<string | undefined>
  /** The settings Claude Code runs under, merged over every source. */
  settings: () => Promise<Readonly<Record<string, unknown>>>
  now: () => Promise<number>
}

/** A transcript counted so far: where it is, how many bytes were read, and what they added up to. */
type Reading = Tally & { path: string | null; offset: number; checkedAt: number }
export type Readings = Map<string, Reading>
/**
 * The session each process inherited, by pid, start time and command. `ps eww`
 * shows the environment a process started with, which only an exec replaces,
 * and an exec changes the command.
 */
export type Envs = Map<string, ProcEnv | null>

/** `ps` prints lstart in the local zone, while the session registry writes procStart in UTC. */
const UTC = { TZ: 'UTC', LC_ALL: 'C' }
/** The engine hands back this much of a command's output, and reads the rest only to drop it. */
const OUTPUT_CAP = 4_194_304
const SESSION_ID = /^[\w-]+$/
const MISSING_TRANSCRIPT_RETRY_MS = 60_000
const DAY_MS = 86_400_000
/** Claude Code's cleanupPeriodDays when no settings name one. */
const RETENTION_DAYS = 30
// ponytail: at most 8 x 4 MiB of a transcript per scan; a longer backlog finishes over the next scans.
const CHUNKS_PER_SCAN = 8
/** Linux: each pid, then the environment it started with, from /proc (what `ps eww` reads on macOS). */
const LINUX_ENVS = `for p; do printf '%s ' "$p"; tr '\\0\\n' '  ' < "/proc/$p/environ" 2>/dev/null; echo; done`
/** Linux: each pid's working folder from /proc, as the `p<pid>` and `n<path>` lines lsof prints. */
const LINUX_CWDS = `for p; do d=$(readlink "/proc/$p/cwd" 2>/dev/null) && printf 'p%s\\nn%s\\n' "$p" "$d"; done`

export async function contextOf(io: Io): Promise<Context> {
  const configDir = (await io.configDir()) || `${(await io.home()) ?? ''}/.claude`
  const { stdout } = await io.run(['/bin/sh', '-c', 'echo "$PPID $(id -u) $(uname -s)"'])
  const [host = '0', uid = '-1', system = ''] = stdout.trim().split(' ')
  const os = osOf(system)
  return { configDir, os, selfHostPid: Number(host), selfUid: Number(uid), machine: await machineOf(io, os) }
}

function osOf(system: string): Os {
  if (system === 'Darwin') return 'darwin'
  if (system === 'Linux') return 'linux'
  throw new Error(`Rest in PID reads macOS and Linux processes, not ${system || 'this system'}'s`)
}

/** The cores and memory the meters measure against; zeros when the probe fails. */
async function machineOf(io: Io, os: Os): Promise<Machine> {
  if (os === 'darwin') {
    const facts = await optional(io.run(['sysctl', '-n', 'hw.ncpu', 'hw.memsize']))
    const [cores = 0, memoryBytes = 0] = facts.trim().split('\n').map(Number)
    return { cores, memoryKb: Math.round(memoryBytes / 1024) }
  }
  const facts = await optional(io.run(['/bin/sh', '-c', 'getconf _NPROCESSORS_ONLN; grep MemTotal /proc/meminfo']))
  return { cores: Number(facts.split('\n')[0]) || 0, memoryKb: Number(/MemTotal:\s+(\d+)/.exec(facts)?.[1] ?? 0) }
}

/** procps takes BSD options only without the dash; macOS ps takes either. */
export async function readPs(io: Io, os: Os): Promise<PsRow[]> {
  const fields = 'pid=,ppid=,pgid=,uid=,stat=,%cpu=,rss=,lstart=,command='
  const argv = os === 'darwin' ? ['ps', '-axww', '-o', fields] : ['ps', 'axww', '-o', fields]
  const { stdout } = await io.run(argv, { env: UTC })
  return parsePs(stdout)
}

/** Output of a probe that may be missing or fail (lsof is not on every host); nothing then. */
async function optional(run: Promise<ProcessRunResult>): Promise<string> {
  try {
    return (await run).stdout
  } catch {
    return ''
  }
}

/**
 * The paths among `paths` that no longer exist. A path the host will not check
 * (it rejects a network location) counts as present, so it never makes a zombie.
 */
async function missing(io: Io, paths: ReadonlyArray<string | null>): Promise<Set<string>> {
  const gone = new Set<string>()
  for (const path of new Set(paths)) {
    if (path !== null && !(await io.exists(path).catch(() => true))) gone.add(path)
  }
  return gone
}

/**
 * Before when a shell snapshot may be gone while its session still runs: Claude Code's retention
 * sweep deletes the ones older than cleanupPeriodDays either way.
 */
async function sweptBefore(io: Io, now: number): Promise<number> {
  const settings = await io.settings().catch((): Readonly<Record<string, unknown>> => ({}))
  const days = settings.cleanupPeriodDays
  return now - (typeof days === 'number' && days >= 0 ? days : RETENTION_DAYS) * DAY_MS
}

async function readEntries(io: Io, configDir: string): Promise<HostEntry[]> {
  const dir = `${configDir}/sessions`
  if (!(await io.exists(dir))) return []
  const files = (await io.list(dir)).filter(file => file.kind === 'file' && file.name.endsWith('.json'))
  const entries = await Promise.all(files.map(async file => parseHost(await io.read(`${dir}/${file.name}`))))
  return entries.filter((entry): entry is HostEntry => entry !== null)
}

async function readingOf(io: Io, configDir: string, sessionId: string, readings: Readings) {
  const now = await io.now()
  let reading = readings.get(sessionId)
  if (reading === undefined || (reading.path === null && now - reading.checkedAt > MISSING_TRANSCRIPT_RETRY_MS)) {
    const found = await io.run([
      'find',
      `${configDir}/projects`,
      '-maxdepth',
      '2',
      '-name',
      `${sessionId}.jsonl`,
    ])
    reading = {
      path: found.stdout.split('\n')[0] || null,
      offset: 0,
      checkedAt: now,
      seen: new Set(),
      tokensIn: 0,
      tokensOut: 0,
    }
    readings.set(sessionId, reading)
  }
  if (reading.path === null) return reading
  const { size } = await io.stat(reading.path)
  if (size < reading.offset) Object.assign(reading, { offset: 0, seen: new Set(), tokensIn: 0, tokensOut: 0 })
  for (let chunk = 0; chunk < CHUNKS_PER_SCAN && reading.offset < size; chunk += 1) {
    // dd seeks to the offset and head stops at what the engine keeps: `tail -c +N` copies byte
    // by byte, and the engine would read the whole rest of the file every time.
    const { stdout } = await io.run([
      '/bin/sh',
      '-c',
      `{ dd bs=1 skip="$1" count=0 2>/dev/null; head -c ${OUTPUT_CAP}; } < "$2"`,
      'sh',
      String(reading.offset),
      reading.path,
    ])
    const end = stdout.lastIndexOf('\n')
    if (end < 0) break
    // Whole lines only: the byte count stays exact, and a cut line is read again next time.
    const lines = stdout.slice(0, end + 1)
    reading.offset += new TextEncoder().encode(lines).length
    tallyUsage(lines, reading)
  }
  return reading
}

const envKey = (row: PsRow): string => `${row.pid} ${row.started} ${row.command}`

/** The command that prints each pid followed by the environment it started with. */
const envProbe = (os: Os, pids: readonly string[]): string[] =>
  os === 'darwin'
    ? ['ps', 'eww', '-o', 'pid=,command=', '-p', pids.join(',')]
    : ['/bin/sh', '-c', LINUX_ENVS, 'sh', ...pids]

/** The command that prints each pid's working folder, as lsof's `p<pid>` and `n<path>` lines. */
const cwdProbe = (os: Os, pids: readonly string[]): string[] =>
  os === 'darwin'
    ? // -b skips the stat and readlink calls that can block (the kernel names the cwd either way).
      ['lsof', '-b', '-w', '-a', '-d', 'cwd', '-Fpn', '-p', pids.join(',')]
    : ['/bin/sh', '-c', LINUX_CWDS, 'sh', ...pids]

/**
 * The session each candidate inherited. Only the ones not read before are
 * asked about; a pid the probe did not print (gone, or the probe failed) is
 * asked again.
 */
async function readEnvs(
  io: Io,
  os: Os,
  rows: readonly PsRow[],
  candidates: ReadonlySet<number>,
  envs: Envs,
): Promise<Map<number, ProcEnv>> {
  const unread = rows.filter(row => candidates.has(row.pid) && !envs.has(envKey(row)))
  const pids = unread.map(row => String(row.pid))
  const stdout = pids.length === 0 ? '' : await optional(io.run(envProbe(os, pids)))
  const found = parseEnv(stdout, new Map(unread.map(row => [row.pid, row.command])))
  const printed = new Set(stdout.split('\n').map(line => Number(/^\s*(\d+)\s/.exec(line)?.[1])))
  const kept: Envs = new Map()
  const env = new Map<number, ProcEnv>()
  for (const row of rows) {
    const key = envKey(row)
    if (!candidates.has(row.pid) || (!envs.has(key) && !printed.has(row.pid))) continue
    const value = envs.has(key) ? (envs.get(key) ?? null) : (found.get(row.pid) ?? null)
    kept.set(key, value)
    if (value !== null) env.set(row.pid, value)
  }
  // Only the processes still running stay remembered.
  envs.clear()
  for (const [key, value] of kept) envs.set(key, value)
  return env
}

export async function scan(io: Io, context: Context, readings: Readings, envs: Envs): Promise<Snapshot> {
  const { os } = context
  const [rows, entries, swept] = await Promise.all([
    readPs(io, os),
    readEntries(io, context.configDir),
    io.now().then(now => sweptBefore(io, now)),
  ])
  const candidates = new Set(candidatesOf(rows, entries, context.selfUid, os))
  const pids = [...candidates].map(String)
  const [env, cwdOut] = await Promise.all([
    readEnvs(io, os, rows, candidates, envs),
    pids.length === 0 ? '' : optional(io.run(cwdProbe(os, pids))),
  ])
  const cwd = parseCwd(cwdOut)
  const { groups, zombies } = classify({
    rows,
    entries,
    env,
    cwd,
    missingWorktrees: await missing(io, [...cwd.values()].map(worktreeOf)),
    // Only a snapshot the retention sweep could not have taken says its session exited.
    missingSnapshots: await missing(
      io,
      rows
        .filter(row => candidates.has(row.pid))
        .map(row => snapshotOf(row.command))
        .map(snapshot => (snapshot !== null && bornOf(snapshot) >= swept ? snapshot : null)),
    ),
    selfUid: context.selfUid,
    os,
  })
  const sessions = [
    ...groups.map(group => group.session),
    ...zombies.flatMap(zombie => (zombie.session === null ? [] : [zombie.session])),
  ]
  for (const session of sessions) {
    if (!SESSION_ID.test(session.sessionId)) continue
    const reading = await readingOf(io, context.configDir, session.sessionId, readings).catch(() => undefined)
    session.tokensIn = reading?.tokensIn ?? 0
    session.tokensOut = reading?.tokensOut ?? 0
  }
  return {
    scannedAt: await io.now(),
    groups,
    zombies,
    totals: totalsOf(groups, zombies),
    machine: context.machine,
    error: null,
  }
}

